Table(
    {
        ItemKey: "addNewChecklistEntity",
        ItemDisplayName: "Add Task",
        ItemIconName: "Add",
        ItemEnabled: true
    },
    {
        ItemKey: "reorderChecklist",
        ItemDisplayName: "Reorder",
        ItemIconName: "NumberedList",
        ItemEnabled: true
    }
)

Switch(
    Self.Selected.ItemKey,
    "addNewChecklistEntity",
    UpdateContext(
        {
            locIsVisibleChecklistRightPanel: true,
            locSelectedChecklistEntity: Blank(),
            locSelectedCluster: ThisItem,
            locTotalRows: CountRows(
                Filter(
                    'Project Default Checklists',
                    'Associated Country And Technology'.'Checklist Country And Technology' = locSelectedCountryAndTechnology.'Checklist Country And Technology',
                    'Cluster State'.'Project State' = ThisItem.'Project State'
                )
            )
        }
    );
    "reorderChecklist",
    UpdateContext(
        {
            locShowReorderForm: true,
            locResetOrderingList: "Reset" & Rand()
        }
    );
    ClearCollect(
        colTasksToReorder,
        Filter(
            'Project Default Checklists',
            'Associated Country And Technology'.'Checklist Country And Technology' = locSelectedCountryAndTechnology.'Checklist Country And Technology',
            'Cluster State'.'Project State' = ThisItem.'Project State'
        )
    )
);

UpdateContext(
    {
        locAdminLoadingDialog: true,
        locAdminLoadingDialogText: $"Completion Date for '{ThisItem.Name}' will be changed, please wait..."
    }
);
IfError(
    UpdateContext(
        {
            locSelectedChecklistEntity: Patch(
                'Project Default Checklists',
                LookUp(
                    'Project Default Checklists',
                    'Project Default Checklist' = ThisItem.'Project Default Checklist'
                ),
                {'Is Completion Date': Not(ThisItem.'Is Completion Date')}
            )
        }
    );
    UpdateContext({locAdminLoadingDialogText: $"Completion Date was successfully changed."});
    Refresh('Project Default Approvals'),
    UpdateContext({locAdminLoadingDialogText: $"Error: Completion Date could not be changed. Internal error: originated on {FirstError.Source}. Message: {FirstError.Message} {FirstError.Details.HttpResponse}"})
);
UpdateContext(
    {
        locAdminLoadingDialog: false,
        locAdminLoadingDialogText: Blank()
    }
);

If(
    Self.DisplayMode = DisplayMode.Edit,
    UpdateContext(
        {
            locIsVisibleChecklistRightPanel: true,
            locSelectedChecklistEntity: ThisItem    
        }
    )
)

If(
    Self.DisplayMode = DisplayMode.Edit,
    UpdateContext(
        {
            locSelectedChecklistEntity: ThisItem,
            locIsVisiblePopUpDeleteDefaultChecklist: true
        }
    )
)

